         'content':"# What I paid for whom\n- Cesar => $23\n- Glenn => $22\n- Matthew => $29\n- Melissa => $15"}

def parse_shares(content):
    shares=defaultdict(float)
    for line in content.splitlines():
        line=line.strip()
        if not line.startswith('-'): 
            continue
        # format: - Name => $Amount
        import re
        m=re.match(r'-\s*(.*?)\s*=>\s*\$\s*([0-9]+(?:\.[0-9]+)?)', line)
        if m:
            name=m.group(1).strip()
            amt=float(m.group(2))
            shares[name]+=amt
    return dict(shares)

shares_total=defaultdict(float)
for n in [note1,note2]:
    s=parse_shares(n['content'])
    for k,v in s.items():
        shares_total[k]+=v

print('shares_total:')
for name,amt in sorted(shares_total.items()):
    print(name, amt)
print('count people:', len(shares_total))

